PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?label (COALESCE(?bd1, ?bd2, ?bd3) AS ?birthDate) WHERE {
  VALUES ?person { dbr:Miko_Mayama dbr:Wangechi }
  OPTIONAL { ?person dbo:birthDate ?bd1. }
  OPTIONAL { ?person dbp:birthDate ?bd2. }
  OPTIONAL { ?person dbp:born ?bd3. }
  OPTIONAL { ?person rdfs:label ?label . FILTER(lang(?label) = "en") }
} ORDER BY ?person

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?person ?label (COALESCE(?bd, ?bd2, ?bd3, ?extracted) AS ?birthDate) ?bd ?bd2 ?bd3 ?comment ?extracted WHERE {
  VALUES ?person { dbr:Miko_Mayama dbr:Wangechi }
  OPTIONAL { ?person dbo:birthDate ?bd. }
  OPTIONAL { ?person dbp:birthDate ?bd2. }
  OPTIONAL { ?person dbp:born ?bd3. }
  OPTIONAL { ?person rdfs:comment ?comment . FILTER(langMatches(lang(?comment), "EN") || langMatches(lang(?comment), "DE") || lang(?comment) = "") }
  OPTIONAL { ?person rdfs:label ?label . FILTER(lang(?label) = "en") }
  BIND(xsd:date(concat(REPLACE(STR(?comment), '.*(\\d{4}).*', '$1'), '-01-01')) AS ?extracted)
} ORDER BY ?person

